export type Constructor<T = any> = abstract new (...args: any[]) => T;

export function isClass(target: any) {
  if (typeof target !== 'function') {
    return false;
  }
  const proto = target.constructor;
  return proto === Function;
}

export function getClass(target: any): Constructor {
  return isClass(target)
    ? (target as Constructor)
    : getClass(target.constructor);
}
