import { Constructor } from './utility';

const MODERN_REGISTRY_TARGETS_KEY = Symbol.for(
  'typed-reflector.modern.registry-targets',
);

type PropertyKey = string | symbol;

export interface ModernRegistryTargets {
  target: object;
  staticProperties: object;
  instanceProperties: object;
}

export interface DecoratorMetadataObject {
  [MODERN_REGISTRY_TARGETS_KEY]?: ModernRegistryTargets;
}

export function ensureSymbolMetadata() {
  const symbolCtor = Symbol as typeof Symbol & { metadata?: symbol };
  if (!symbolCtor.metadata) {
    Object.defineProperty(symbolCtor, 'metadata', {
      value: Symbol('Symbol.metadata'),
      configurable: true,
    });
  }

  return symbolCtor.metadata!;
}

export function ensureRegistryTargets(metadata: DecoratorMetadataObject) {
  if (
    Object.prototype.hasOwnProperty.call(metadata, MODERN_REGISTRY_TARGETS_KEY)
  ) {
    return metadata[MODERN_REGISTRY_TARGETS_KEY]!;
  }

  const parent = Object.getPrototypeOf(metadata) as
    | DecoratorMetadataObject
    | undefined;
  const parentTargets = parent ? ensureRegistryTargets(parent) : undefined;
  const targets: ModernRegistryTargets = {
    target: Object.create(parentTargets?.target ?? null),
    staticProperties: Object.create(parentTargets?.staticProperties ?? null),
    instanceProperties: Object.create(
      parentTargets?.instanceProperties ?? null,
    ),
  };
  metadata[MODERN_REGISTRY_TARGETS_KEY] = targets;
  return targets;
}

export function getClassMetadataObject(target: Constructor) {
  const symbolMetadata = ensureSymbolMetadata();
  return (
    target as Constructor & {
      [key: symbol]: DecoratorMetadataObject | undefined;
    }
  )[symbolMetadata];
}

export function getRegistryTarget(
  metadata: DecoratorMetadataObject,
  isStatic: boolean | undefined,
  propertyKey?: PropertyKey,
) {
  const targets = ensureRegistryTargets(metadata);
  if (propertyKey === undefined) {
    return targets.target;
  }

  return isStatic ? targets.staticProperties : targets.instanceProperties;
}

export function getRequiredMetadataObject<
  T extends { metadata?: DecoratorMetadataObject | null | undefined },
>(context: T) {
  const metadata = context.metadata as DecoratorMetadataObject | undefined;
  if (!metadata) {
    throw new Error(
      'Standard decorator metadata is unavailable. Polyfill Symbol.metadata before evaluating decorators.',
    );
  }

  return metadata;
}
