import { GenericMap, Key, MergeKey, StringDict } from './def';
import { BaseReflector } from './base-reflector';
import { UniversalDecorators } from './def-universal';
import { getClass } from './utility/utility';
import {
  ensureSymbolMetadata,
  getRequiredMetadataObject,
  getRegistryTarget,
} from './utility/modern-decorator-targets';

type PropertyKey = string | symbol;

type ModernDecoratorContext =
  | ClassDecoratorContext
  | ClassFieldDecoratorContext
  | ClassMethodDecoratorContext
  | ClassGetterDecoratorContext
  | ClassSetterDecoratorContext
  | ClassAccessorDecoratorContext;

type UniversalContext =
  | { mode: 'legacy'; target: object; key?: string | symbol }
  | { mode: 'modern'; context: ModernDecoratorContext };

function isDecoratorContext(value: unknown): value is ModernDecoratorContext {
  return (
    !!value &&
    typeof value === 'object' &&
    'kind' in value &&
    typeof (value as { kind?: unknown }).kind === 'string'
  );
}

ensureSymbolMetadata();

export class Reflector<
  M extends StringDict,
  AM extends StringDict,
> extends BaseReflector<M, AM, UniversalContext, UniversalDecorators> {
  protected resolveDecoratorMetadataTarget(context: UniversalContext) {
    if (context.mode === 'legacy') {
      return { target: context.target, key: context.key };
    }

    const modernContext = context.context;
    const metadata = getRequiredMetadataObject(modernContext);
    return {
      target: getRegistryTarget(
        metadata,
        modernContext.kind === 'class' ? undefined : modernContext.static,
        modernContext.kind === 'class'
          ? undefined
          : (modernContext.name as PropertyKey),
      ),
      key:
        modernContext.kind === 'class'
          ? undefined
          : (modernContext.name as string | symbol | undefined),
    };
  }

  protected resolveKeysIndexContext(context: UniversalContext) {
    if (context.mode === 'legacy') {
      if (context.key === undefined) {
        return undefined;
      }

      return { mode: 'legacy', target: getClass(context.target) } as const;
    }

    if (
      context.context.kind === 'class' ||
      context.context.name === undefined
    ) {
      return undefined;
    }

    return {
      mode: 'modern' as const,
      context: { ...context.context, kind: 'class' } as ModernDecoratorContext,
    };
  }

  protected resolveIndexedKey(context: UniversalContext) {
    if (context.mode === 'legacy') {
      return context.key;
    }

    return context.context.kind === 'class'
      ? undefined
      : (context.context.name as string | symbol | undefined);
  }

  protected createDecorator<
    K extends MergeKey<M, AM>,
    IK extends Key<AM>,
    GM extends Record<MergeKey<M, AM>, any> = GenericMap<M, AM>,
  >(
    metadataKey: K,
    metadataValueFun: (oldValue: GM[K]) => GM[K],
    keysIndexMeta?: IK,
  ): UniversalDecorators {
    return ((...args: any[]) => {
      if (isDecoratorContext(args[1])) {
        const context = { mode: 'modern', context: args[1] } as const;
        this.applyMetadataTransform<K, GM>(
          metadataKey,
          metadataValueFun,
          context,
          keysIndexMeta,
        );
        return args[0];
      }

      const context = {
        mode: 'legacy',
        target: args[0] as object,
        key: args[1] as string | symbol | undefined,
      } as const;
      this.applyMetadataTransform<K, GM>(
        metadataKey,
        metadataValueFun,
        context,
        keysIndexMeta,
      );
      return undefined;
    }) as unknown as UniversalDecorators;
  }
}

export { Reflector as MetadataSetter };
export { ensureSymbolMetadata };
export type { ReflectorOptions } from './base-reflector';
